package com.adamstz.protectitemalarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;

public class AlarmOverlay extends OverlayPanel
{
	private static final Color TRANSPARENT = new Color(0, 0, 0, 0);

	private final Client client;
	private final ProtectItemAlarmConfig config;

	@Inject
	private AlarmOverlay(Client client, ProtectItemAlarmConfig config)
	{
		this.client = client;
		this.config = config;
		setPriority(PRIORITY_LOW);
		setMovable(false);
		setSnappable(false);
		setDragTargetable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FlashSpeed speed = config.flashSpeed();

		switch (speed)
		{
			case OFF:
				graphics.setColor(TRANSPARENT);
				break;
			case SOLID:
				graphics.setColor(config.flashColor());
				break;
			default:
				if ((client.getGameCycle() % speed.getRate()) >= (speed.getRate() / 2))
				{
					graphics.setColor(config.flashColor());
				}
				else
				{
					graphics.setColor(TRANSPARENT);
				}
				break;
		}

		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return client.getCanvas().getSize();
	}
}

package com.adamstz.protectitemalarm;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum FlashSpeed
{
	OFF("Off", -1),
	SLOW("Slow", 80),
	NORMAL("Normal", 40),
	FAST("Fast", 20),
	SOLID("Solid color", -1);

	private final String label;
	private final int rate;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.adamstz.protectitemalarm;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("protectitemalarm")
public interface ProtectItemAlarmConfig extends Config
{
	@ConfigItem(
		position = 0,
		keyName = "flashSpeed",
		name = "Flash speed",
		description = "Cadence at which the screen flashes while you're unprotected and at risk. 'Off' disables the flash entirely."
	)
	default FlashSpeed flashSpeed()
	{
		return FlashSpeed.NORMAL;
	}

	@Alpha
	@ConfigItem(
		position = 1,
		keyName = "flashColor",
		name = "Flash color",
		description = "Color of the alarm screen flash."
	)
	default Color flashColor()
	{
		return new Color(255, 0, 0, 70);
	}

	@ConfigItem(
		position = 2,
		keyName = "onlyWhenSkulled",
		name = "Only alarm when skulled",
		description = "Restrict the alarm to only fire while your character is skulled, instead of any PvP-risk area."
	)
	default boolean onlyWhenSkulled()
	{
		return false;
	}

	@ConfigItem(
		position = 3,
		keyName = "hideOnHighRiskWorlds",
		name = "Ignore High Risk worlds",
		description = "Suppress the alarm entirely on High Risk PvP worlds."
	)
	default boolean hideOnHighRiskWorlds()
	{
		return false;
	}
}

package com.adamstz.protectitemalarm;

import com.google.inject.Provides;
import java.util.EnumSet;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.SkullIcon;
import net.runelite.api.WorldType;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Protect Item Alarm",
	description = "Flashes the screen when Protect Item isn't active while you're in a PvP-risk area",
	tags = {"wilderness", "wildy", "protect", "risk", "pvp", "pk", "alarm", "skull"}
)
public class ProtectItemAlarmPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ProtectItemAlarmConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AlarmOverlay overlay;

	// Whether the flashing overlay is currently added to the overlay manager.
	private boolean overlayOn;

	@Override
	protected void startUp()
	{
		resetAlarmState();
		log.debug("Protect Item Alarm started");
	}

	@Override
	protected void shutDown()
	{
		resetAlarmState();
		log.debug("Protect Item Alarm stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!shouldAlarm())
		{
			resetAlarmState();
			return;
		}

		if (!overlayOn)
		{
			overlayOn = true;
			overlayManager.add(overlay);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.LOGGING_IN || state == GameState.CONNECTION_LOST)
		{
			resetAlarmState();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player local = client.getLocalPlayer();
		if (local != null && event.getActor() == local)
		{
			resetAlarmState();
		}
	}

	private boolean shouldAlarm()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		if (isProtectItemActive())
		{
			return false;
		}

		if (config.onlyWhenSkulled() && local.getSkullIcon() == SkullIcon.NONE)
		{
			return false;
		}

		EnumSet<WorldType> worldType = client.getWorldType();

		if (config.hideOnHighRiskWorlds() && worldType.contains(WorldType.HIGH_RISK))
		{
			return false;
		}

		return isInRiskArea(worldType);
	}

	private boolean isProtectItemActive()
	{
		// Client.isPrayerActive(Prayer) is deprecated (mishandles overlapping prayer conflicts),
		// so check the underlying varbits directly instead, covering both the normal and
		// Ruinous Powers variants of Protect Item.
		return client.getVarbitValue(VarbitID.PRAYER_PROTECTITEM) == 1
			|| client.getVarbitValue(VarbitID.PRAYER_PROTECT_ITEM_R) == 1;
	}

	private boolean isInRiskArea(EnumSet<WorldType> worldType)
	{
		if (worldType.contains(WorldType.DEADMAN)
			|| worldType.contains(WorldType.SEASONAL)
			|| worldType.contains(WorldType.TOURNAMENT_WORLD)
			|| worldType.contains(WorldType.PVP_ARENA))
		{
			// Deadman: can't protect item anyway. Leagues/PvP arena: safe pvp rulesets.
			return false;
		}

		if (worldType.contains(WorldType.PVP) || worldType.contains(WorldType.HIGH_RISK))
		{
			return client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1;
		}

		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1;
	}

	private void resetAlarmState()
	{
		if (overlayOn)
		{
			overlayOn = false;
			overlayManager.remove(overlay);
		}
	}

	@Provides
	ProtectItemAlarmConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ProtectItemAlarmConfig.class);
	}
}

package com.adamstz.protectitemalarm;

